#pragma once

#include <carb/RString.h>

namespace omni
{
namespace timeline
{

/**
 * Defines timeline event types to be used by TimelineEventStream.
 */
enum class TimelineEventType
{
    ePlay, /**< Timeline started to play. */
    ePause, /**< Timeline paused. */
    eStop, /**< Timeline stopped. */
    eCurrentTimeChanged, /**< Deprecated. No longer used. */
    eCurrentTimeTickedPermanent, /**< Current time is ticked by update function (called per subframe=tick even if not playing). */
    eCurrentTimeTicked, /**< Current time is ticked by update function (called per subframe=tick when playing). */
    eLoopModeChanged, /**< Looping mode changed. */
    eStartTimeChanged, /**< Start time changed. */
    eEndTimeChanged, /**< End time changed. */
    eTimeCodesPerSecondChanged, /**< Timecode per second (animation framerate) changed. */
    eAutoUpdateChanged, /**< Auto update changed. */
    ePrerollingChanged, /**< Prerolling changed. */
    eTentativeTimeChanged, /**< Tentative current time is changed by user (isn't called when timeline ticked). */
    eTicksPerFrameChanged, /**< Ticks per frame count changed. */
    ePlayEveryFrameChanged, /**< Play every frame (no frame skipping) changed. */
    eFastModeChanged = ePlayEveryFrameChanged, /**< Fast mode changed. Same as ePlayEveryFrameChanged, kept for backward compatibility. */
    eTargetFramerateChanged, /**< Target runloop frame rate changed. */
    eDirectorChanged, /**< Timeline is driven by a new director timeline. */
    eZoomChanged /**< Zoom range changed. */
};

//! events Event Constants
//! @warning Make sure to filter events by timeline name.
//! @{
const auto kGlobalEventPlay = carb::RString("omni.timeline:timeline:play"); /**< Timeline started to play. */
const auto kGlobalEventPause = carb::RString("omni.timeline:timeline:pause"); /**< Timeline paused. */
const auto kGlobalEventStop = carb::RString("omni.timeline:timeline:stop"); /**< Timeline stopped. */
const auto kGlobalEventCurrentTimeTickedPermanent = carb::RString("omni.timeline:timeline:current_time_ticked_permanent"); /**< Current time is ticked by update function (called per subframe=tick even if not playing). */
const auto kGlobalEventCurrentTimeTicked = carb::RString("omni.timeline:timeline:current_time_ticked"); /**< Current time is ticked by update function (called per subframe=tick when playing). */
const auto kGlobalEventLoopModeChanged = carb::RString("omni.timeline:timeline:loop_mode_changed"); /**< Looping mode changed. */
const auto kGlobalEventStartTimeChanged = carb::RString("omni.timeline:timeline:start_time_changed"); /**< Start time changed. */
const auto kGlobalEventEndTimeChanged = carb::RString("omni.timeline:timeline:end_time_changed"); /**< End time changed. */
const auto kGlobalEventTimeCodesPerSecondChanged = carb::RString("omni.timeline:timeline:timecodes_per_second_changed"); /**< Timecode per second (animation framerate) changed. */
const auto kGlobalEventAutoUpdateChanged = carb::RString("omni.timeline:timeline:auto_update_changed"); /**< Auto update changed. */
const auto kGlobalEventPrerollingChanged = carb::RString("omni.timeline:timeline:prerolling_changed"); /**< Prerolling changed. */
const auto kGlobalEventTentativeTimeChanged = carb::RString("omni.timeline:timeline:tentative_time_changed"); /**< Tentative current time is changed by user (isn't called when timeline ticked). */
const auto kGlobalEventTicksPerFrameChanged = carb::RString("omni.timeline:timeline:ticks_per_frame_changed"); /**< Ticks per frame count changed. */
const auto kGlobalEventPlayEveryFrameChanged = carb::RString("omni.timeline:timeline:play_every_frame_changed"); /**< Play every frame (no frame skipping) changed. */
const auto kGlobalEventTargetFramerateChanged = carb::RString("omni.timeline:timeline:target_framerate_changed"); /**< Target runloop frame rate changed. */
const auto kGlobalEventDirectorChanged = carb::RString("omni.timeline:timeline:director_changed"); /**< Timeline is driven by a new director timeline. */
const auto kGlobalEventZoomChanged = carb::RString("omni.timeline:timeline:zoom_changed"); /**< Zoom range changed. */
//! @}

}
}
